node --input-type=module <<'NODE'
import fs from 'node:fs';
import { createHash } from 'node:crypto';
const hash = path => createHash('sha256').update(fs.readFileSync(path)).digest('hex');
const baselinePath = 'docs/remediation/design/W09.03/baseline.json';
const baseline = JSON.parse(fs.readFileSync(baselinePath, 'utf8'));
const owned = new Set(baseline.owned.map(file => file.path));
const protectedPins = baseline.pins.filter(file => !owned.has(file.path));
const mismatches = protectedPins.filter(file => hash(file.path) !== file.sha256).map(file => file.path);
const result = { final_source_stop: { at: new Date().toISOString(), files: baseline.owned.map(file => ({ path: file.path, sha256: hash(file.path) })) }, protected_source_comparison: { checked: protectedPins.length, mismatches }, baseline_sha256: hash(baselinePath), plan_sha256: hash('docs/remediation/design/W09.03/plan.md') };
console.log(JSON.stringify(result, null, 2));
if (mismatches.length) process.exitCode = 1;
NODE
